   263→    public function store(Request $request)
   264→    {
   265→        $request->validate([
   266→            'name' => 'required',
   267→            'city' => 'required',
   268→            'email' => 'nullable|email',
   269→            'password' => 'nullable|min:6',
   270→            'admin_name' => 'nullable|string',
   271→            'admin_username' => 'nullable|string',
   272→        ]);
   273→
   274→        // Determine feature flags from either pages[] (new UI) or legacy can_* inputs
   275→        $pagesSelected = $request->input('pages');
   276→        if (is_array($pagesSelected) && count($pagesSelected)) {
   277→            $can_students = in_array('student', $pagesSelected);
   278→            $can_teachers = in_array('teacher', $pagesSelected) || in_array('employee', $pagesSelected);
   279→            $can_schedules = in_array('schedule', $pagesSelected);
   280→            $can_payments = in_array('payment', $pagesSelected);
   281→            $can_tryouts = in_array('tryout', $pagesSelected);
   282→        } else {
   283→            $can_students = $request->has('can_students');
   284→            $can_teachers = $request->has('can_teachers');
   285→            $can_schedules = $request->has('can_schedules');
   286→            $can_payments = $request->has('can_payments');
   287→            $can_tryouts = $request->has('can_tryouts');
   288→        }
   289→
   290→        // create branch first (without admin_id)
   291→        $branch = Branch::create([
   292→            'name' => $request->name,
   293→            'city' => $request->city,
   294→            'regency' => $request->regency,
   295→            'address' => $request->address,
   296→            'phone' => $request->phone,
   297→            'email' => $request->email,
   298→            'status' => 'active',
   299→            'can_students' => $can_students,
   300→            'can_teachers' => $can_teachers,
   301→            'can_schedules' => $can_schedules,
   302→            'can_payments' => $can_payments,
   303→            'can_tryouts' => $can_tryouts,
   304→            'allowed_pages' => is_array($pagesSelected) ? array_values($pagesSelected) : [],
   305→            'created_by' => auth()->id(),
   306→        ]);
   307→
   308→        // create admin user if email provided
   309→        if ($request->email && $request->password) {
   310→            $user = User::firstOrCreate(
   311→                ['email' => $request->email],
   312→                [
   313→                    'name' => $request->admin_name ?? $request->email,
   314→                    'username' => $request->admin_username ?? null,
   315→                    'password' => Hash::make($request->password),
   316→                    'is_active' => true,
   317→                ]
   318→            );
   319→
   320→            // assign role admin
   321→            if (method_exists($user, 'assignRole')) {
   322→                $user->assignRole('admin');
   323→            }
   324→
   325→            // link user to branch and save relation
   326→            $user->branch_id = $branch->id;
   327→            $user->save();
   328→
   329→            $branch->admin_id = $user->id;
   330→            $branch->save();
   331→        }
   332→
   333→        return back()->with('success', 'Cabang berhasil dibuat');
   334→    }
