   336→    public function update(Request $request, Branch $branch)
   337→    {
   338→        $request->validate([
   339→            'name' => 'required',
   340→            'city' => 'required',
   341→            'status' => 'nullable',
   342→            'email' => 'nullable|email',
   343→            'password' => 'nullable|min:6',
   344→            'admin_name' => 'nullable|string',
   345→            'admin_username' => 'nullable|string',
   346→        ]);
   347→
   348→        // Determine feature flags from either pages[] (new UI) or legacy can_* inputs
   349→        $pagesSelected = $request->input('pages');
   350→        if (is_array($pagesSelected) && count($pagesSelected)) {
   351→            $can_students = in_array('student', $pagesSelected);
   352→            $can_teachers = in_array('teacher', $pagesSelected) || in_array('employee', $pagesSelected);
   353→            $can_schedules = in_array('schedule', $pagesSelected);
   354→            $can_payments = in_array('payment', $pagesSelected);
   355→            $can_tryouts = in_array('tryout', $pagesSelected);
   356→            $allowed_pages = array_values($pagesSelected);
   357→        } else {
   358→            $can_students = $request->has('can_students');
   359→            $can_teachers = $request->has('can_teachers');
   360→            $can_schedules = $request->has('can_schedules');
   361→            $can_payments = $request->has('can_payments');
   362→            $can_tryouts = $request->has('can_tryouts');
   363→            $allowed_pages = $branch->allowed_pages ?? [];
   364→        }
   365→
   366→        $branch->update([
   367→            'name' => $request->name,
   368→            'city' => $request->city,
   369→            'regency' => $request->regency ?? $branch->regency,
   370→            'address' => $request->address ?? $branch->address,
   371→            'phone' => $request->phone ?? $branch->phone,
   372→            'email' => $request->email ?? $branch->email,
   373→            'status' => $request->status ?? $branch->status,
   374→            'can_students' => $can_students,
   375→            'can_teachers' => $can_teachers,
   376→            'can_schedules' => $can_schedules,
   377→            'can_payments' => $can_payments,
   378→            'can_tryouts' => $can_tryouts,
   379→            'allowed_pages' => is_array($allowed_pages) ? $allowed_pages : [],
   380→            'updated_by' => auth()->id(),
   381→        ]);
   382→
   383→        // Handle admin account creation/update
   384→        $email = $request->input('email');
   385→        $password = $request->input('password');
   386→        $adminName = $request->input('admin_name');
   387→        $adminUsername = $request->input('admin_username');
   388→
   389→        $admin = $branch->admin;
   390→
   391→        if ($admin) {
   392→            $data = [];
   393→            if (! empty($adminName)) $data['name'] = $adminName;
   394→            if (! empty($adminUsername)) $data['username'] = $adminUsername;
   395→            if (! empty($email)) $data['email'] = $email;
   396→            if (! empty($password)) $data['password'] = Hash::make($password);
   397→            if (! empty($data)) {
   398→                $admin->update($data);
   399→            }
   400→            if (method_exists($admin, 'assignRole')) {
   401→                $admin->assignRole('admin');
   402→            }
   403→            $admin->branch_id = $branch->id;
   404→            $admin->save();
   405→            $branch->admin_id = $admin->id;
   406→            $branch->save();
   407→        } else {
   408→            // create admin if email+password provided
   409→            if (! empty($email) && ! empty($password)) {
   410→                $user = User::firstOrCreate(
   411→                    ['email' => $email],
   412→                    [
   413→                        'name' => $adminName ?? $email,
   414→                        'username' => $adminUsername ?? null,
   415→                        'password' => Hash::make($password),
   416→                        'is_active' => true,
   417→                    ]
   418→                );
   419→                if (method_exists($user, 'assignRole')) {
   420→                    $user->assignRole('admin');
   421→                }
   422→                $user->branch_id = $branch->id;
   423→                $user->save();
   424→                $branch->admin_id = $user->id;
   425→                $branch->save();
   426→            }
   427→        }
   428→
   429→        return back()->with('success', 'Cabang berhasil diupdate');
   430→    }
