   441→    public function resetPassword(Request $request, Branch $branch)
   442→{
   443→    $request->validate([
   444→        'password' => 'required|min:6'
   445→    ]);
   446→
   447→    if ($branch->admin && $branch->admin->exists()) {
   448→        $branch->admin->update(['password' => Hash::make($request->password)]);
   449→    } else {
   450→        $branch->update(['password' => Hash::make($request->password)]);
   451→    }
   452→
   453→    return back()->with('success', 'Password cabang berhasil direset');
   454→}
