function testPage(\$kernel, \$url, \$user) {
    \$request = Illuminate\Http\Request::create(\$url, 'GET');
    \$request->setLaravelSession(app('session.store'));

    \$guard = auth()->guard();
    \$guard->setUser(\$user);

    try {
        \$response = \$kernel->handle(\$request);
        \$status = \$response->getStatusCode();
        \$body = \$response->getContent();

        // Check for exception patterns
        \$hasError = str_contains(\$body, 'Whoops') || str_contains(\$body, 'ErrorException') || str_contains(\$body, 'Fatal error');

        return [
            'status' => \$status,
            'size' => strlen(\$body),
            'has_error' => \$hasError,
            'error_snippet' => \$hasError ? substr(strip_tags(\$body), 0, 200) : null,
        ];
    } catch(\\Throwable \$e) {
        return ['status' => 0, 'error' => \$e->getMessage()];
    }
